BEGIN;
CREATE SCHEMA IF NOT EXISTS agroway_product; CREATE TABLE IF NOT EXISTS agroway_product.manifest(tenant_id uuid NOT NULL,manifest_id uuid NOT NULL,product_id uuid NOT NULL,state text NOT NULL,identity jsonb NOT NULL,provenance text NOT NULL,created_at timestamptz NOT NULL,PRIMARY KEY(tenant_id,manifest_id)); CREATE TABLE IF NOT EXISTS agroway_product.product_version(tenant_id uuid NOT NULL,product_version_id uuid NOT NULL,product_id uuid NOT NULL,version integer NOT NULL,identity_snapshot jsonb NOT NULL,technical_status text NOT NULL,published_at timestamptz,PRIMARY KEY(tenant_id,product_version_id)); CREATE TABLE IF NOT EXISTS agroway_product.sku(tenant_id uuid NOT NULL,sku_id uuid NOT NULL,product_version_id uuid NOT NULL,code text NOT NULL,unit text NOT NULL,active boolean NOT NULL DEFAULT true,PRIMARY KEY(tenant_id,sku_id),UNIQUE(tenant_id,code));
COMMIT;
